{
  "checks": [
    {
      "scenario": "REQ-6.1#1",
      "requirement": "REQ-6.1",
      "title": "Items and styling",
      "category": "navigation",
      "rationale": "Fresh browser opens '/' (home). The home page shows an open sidebar by default. Sidebar navigation items (Notes, Archived, Trash, Reminders) are accessible by their visible text. Consistent icons and styling are not directly observable through text/DOM, so that portion is marked unknown.",
      "given": [],
      "when": [
        { "op": "open" }
      ],
      "then": [
        { "op": "expectText", "target": { "name": ["Notes"], "via": "text", "exact": true } },
        { "op": "expectText", "target": { "name": ["Archived"], "via": "text", "exact": true } },
        { "op": "expectText", "target": { "name": ["Trash"], "via": "text", "exact": true } },
        { "op": "expectText", "target": { "name": ["Reminders"], "via": "text", "exact": true } },
        { "op": "unknown", "reason": "ambiguous-assertion", "detail": "Consistent icons and alignment styling cannot be verified via text/DOM observations." }
      ]
    },
    {
      "scenario": "REQ-6.2#1",
      "requirement": "REQ-6.2",
      "title": "Collapsible Sidebar",
      "category": "navigation",
      "rationale": "Fresh browser opens '/' with the sidebar expanded by default. The sidebar collapse control toggles between expanded and collapsed states. First click hides the 'Notes' text label (icon-only view); second click restores it. The target regex covers common accessible names for the collapse control.",
      "given": [
        { "op": "open" }
      ],
      "when": [
        { "op": "click", "target": { "name": [{ "regex": "collapse sidebar|hide sidebar|minimize sidebar|sidebar collapse", "flags": "i" }], "via": "ladder" } },
        { "op": "expectState", "target": { "name": ["Notes"], "via": "text", "exact": true }, "state": "hidden", "value": true },
        { "op": "click", "target": { "name": [{ "regex": "collapse sidebar|hide sidebar|minimize sidebar|sidebar collapse", "flags": "i" }], "via": "ladder" } }
      ],
      "then": [
        { "op": "expectState", "target": { "name": ["Notes"], "via": "text", "exact": true }, "state": "visible", "value": true }
      ]
    }
  ]
}
